"""File storage behind a small interface, so local disk can be swapped for
S3/GCS later without touching the services.

Rules that hold for any implementation:
  * storage is never public. There is no static route to it; bytes only
    leave through GET /files/{id}/download, after an RLS-checked lookup.
  * keys are generated by us (agency id + random hex), never derived from
    the user's filename, so a filename like "../../etc/passwd" can't
    reach the filesystem.
"""
import os
import pathlib
import tempfile
from collections.abc import Iterator
from typing import BinaryIO, Protocol

CHUNK_SIZE = 64 * 1024


class EmptyFile(Exception):
    pass


class FileTooLarge(Exception):
    pass


class StoredFileMissing(Exception):
    pass


class FileStorage(Protocol):
    def save(self, key: str, stream: BinaryIO, max_bytes: int) -> int:
        """Store the stream under key. Returns its size in bytes."""

    def open_chunks(self, key: str) -> Iterator[bytes]:
        """Yield the stored bytes in chunks."""

    def delete(self, key: str) -> None: ...


class LocalDiskStorage:
    def __init__(self, root: pathlib.Path) -> None:
        self.root = root.resolve()

    def _path(self, key: str) -> pathlib.Path:
        path = (self.root / key).resolve()
        # Keys are ours, but check anyway: never touch anything outside root.
        if not path.is_relative_to(self.root):
            raise ValueError("storage key escapes the storage root")
        return path

    def save(self, key: str, stream: BinaryIO, max_bytes: int) -> int:
        path = self._path(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        size = 0
        # Write to a temp file and rename at the end, so a failed or
        # too-large upload never leaves a half-written file under its key.
        fd, tmp_name = tempfile.mkstemp(dir=path.parent, prefix=".upload-")
        try:
            with os.fdopen(fd, "wb") as out:
                while chunk := stream.read(CHUNK_SIZE):
                    size += len(chunk)
                    if size > max_bytes:
                        raise FileTooLarge
                    out.write(chunk)
            if size == 0:
                raise EmptyFile
            os.replace(tmp_name, path)
        except BaseException:
            pathlib.Path(tmp_name).unlink(missing_ok=True)
            raise
        return size

    def open_chunks(self, key: str) -> Iterator[bytes]:
        path = self._path(key)
        try:
            handle = path.open("rb")
        except FileNotFoundError:
            raise StoredFileMissing(key) from None

        def chunks() -> Iterator[bytes]:
            with handle:
                while chunk := handle.read(CHUNK_SIZE):
                    yield chunk

        return chunks()

    def delete(self, key: str) -> None:
        self._path(key).unlink(missing_ok=True)
